query mrStatus($fullPath: ID!, $iid: String!) {
  project(fullPath: $fullPath) {
    mergeRequest(iid: $iid) {
      iid title state draft
      sourceBranch targetBranch webUrl
      detailedMergeStatus
      mergeable
      conflicts
      headPipeline { id status }
    }
  }
}`;

