    cancel_pipeline: {
      description:
        "Cancel a running pipeline. Unlike retry_pipeline, this stops a " +
        "pipeline that is still in progress instead of re-running a finished one.",
      arguments: z.object({
        project: z.string().min(1),
        pipelineId: z.number(),
